    ctx.fill();
    ctx.strokeStyle = '#6ea8ff';
    ctx.lineWidth = 4;
    ctx.lineJoin = 'round';
    ctx.shadowColor = 'rgba(110, 168, 255, 0.55)';
    ctx.shadowBlur = 14;
    ctx.stroke();
    ctx.shadowBlur = 0;

