    for (var bi = 0; bi < balls.length; bi++) {
      var b = balls[bi];
      ctx.save();
      ctx.translate(b.x, b.y);
      ctx.rotate(b.rot);
      var hue = (b.id * (360 / NUM) + 200) % 360;
      var grad = ctx.createRadialGradient(-5, -6, 2, 0, 0, BALL_R);
      grad.addColorStop(0, 'hsl(' + hue + ', 80%, 74%)');
      grad.addColorStop(1, 'hsl(' + hue + ', 72%, 44%)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, 0, BALL_R, 0, 2 * Math.PI);
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 13px "Segoe UI", system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(String(b.id), 0, 0.5);
      ctx.restore();
    }

    // HUD discreto
    ctx.fillStyle = 'rgba(226, 235, 250, 0.72)';
    ctx.font = '12px "Segoe UI", system-ui, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText('t = ' + t.toFixed(2) + ' s    \u00b7    non\u00e1gono \u00b7 360\u00b0 em 7 s \u00b7 e = 0.82', 16, 24);
  }

  draw();

  /* ------------------- animação (rAF) --------------------------- */
  if (typeof requestAnimationFrame === 'function') {
    var last = null;
    requestAnimationFrame(function frame(now) {
      if (last === null) last = now;
      var dt = (now - last) / 1000;
      last = now;
      dt = Math.max(0, Math.min(dt, 0.05));
      if (!manual && dt > 0) advance(dt); // pára de avançar quando __bench.step toma a condução
      draw();
      requestAnimationFrame(frame);
    });
  }
})();
</script>
</body>
</html>
