          }
        }
      }
      // pares
      var MIN = 2 * BALL_R;
      for (var i2 = 0; i2 < balls.length; i2++) {
        for (var j2 = i2 + 1; j2 < balls.length; j2++) {
          var A = balls[i2], B = balls[j2];
          var dx = B.x - A.x, dy = B.y - A.y;
          var d2 = dx * dx + dy * dy;
          if (d2 >= MIN * MIN) continue;
          var d = Math.sqrt(d2);
          var nx, ny;
          if (d < 1e-9) { nx = 1; ny = 0; d = 0; }
          else { nx = dx / d; ny = dy / d; }
          var p2 = (MIN - d) / 2 + 0.005;
          A.x -= p2 * nx; A.y -= p2 * ny;
          B.x += p2 * nx; B.y += p2 * ny;
