html = r'''<!DOCTYPE html>
<html lang="pt">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bolas em nonágono giratório</title>
<style>
  html, body {
    margin: 0;
    min-height: 100vh;
    background: #0b0e14;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  canvas { display: block; }
</style>
</head>
<body>
<canvas id="cv" width="640" height="640"></canvas>
<script>
"use strict";
(function () {
  /* ----------------------- configuração ----------------------- */
  var N = 9;                     // nonágono regular (9 lados)
  var POLY_R = 260;              // raio do polígono (px)
  var PERIOD = 7;                // 360° em 7 s
  var OMEGA = 2 * Math.PI / PERIOD; // rad/s; positivo = horário no ecrã (eixo y para baixo)
  var APO = POLY_R * Math.cos(Math.PI / N); // apótema (distância centro -> lado)

  var BALL_R = 14;               // raio de cada bola (px)
  var NUM = 13;                  // número de bolas

  var GRAV = 1000;               // gravidade (px/s^2)
  var REST = 0.82;               // restituição
  var AIR_K = 0.35;              // fricção do ar (lineares, 1/s)
  var WALL_FRIC = 0.22;          // fricção de contacto bola-parede (componente tangencial)
  var BALL_FRIC = 0.12;          // fricção de contacto bola-bola
  var MAX_H = 1 / 240;           // passo máximo de integração (s)

  /* ----------------------- ambiente ---------------------------- */
  var canvas = null, ctx = null;
  var W = 640, H = 640;
  if (typeof document !== 'undefined' && document.getElementById) {
    canvas = document.getElementById('cv');
    if (canvas) {
      W = canvas.width;
      H = canvas.height;
      try { ctx = canvas.getContext('2d'); } catch (e) { ctx = null; }
    }
  }
  var CX = W / 2, CY = H / 2;    // centro do canvas (e do polígono)

  /* ------------------------- estado ---------------------------- */
  var t = 0;                     // segundos desde o início
  var manual = false;            // true quando a simulação é movida por __bench.step
  var balls = [];

  (function initBalls() {
    var GA = 2.39996322972865332; // ângulo áureo — distribuição simétrica e sem sobreposições
    for (var i = 0; i < NUM; i++) {
      var a = i * GA;
      var rr = (i === 0) ? 0 : 26 * Math.sqrt(i);
      balls.push({
        id: i,
        x: CX + rr * Math.cos(a),
        y: CY + rr * Math.sin(a),
        vx: 0, vy: 0,
        rot: i * 0.35            // rotação do número desenhado (visível spin)
      });
    }
  })();

  function polyAngle() { return OMEGA * t; }

  /* -------------------- colisão (própria) ----------------------- */

  // Bola-parede: a parede está em rotação rígida, por isso a velocidade da
  // parede no ponto de contacto tem de entrar na resposta à colisão.
  function resolveWalls(h) {
    var ang = polyAngle();
    for (var bi = 0; bi < balls.length; bi++) {
      var b = balls[bi];
      for (var i = 0; i < N; i++) {
        var a = ang + (i + 0.5) * (2 * Math.PI / N);
        var mx = Math.cos(a), my = Math.sin(a);      // normal unitária exterior (centro -> lado)
        var g = APO - ((b.x - CX) * mx + (b.y - CY) * my); // folga centro-da-bola até à linha do lado
        if (g >= BALL_R) continue;

        // ponto de contacto: projeção do centro sobre a linha do lado
        var px = b.x - g * mx, py = b.y - g * my;
        // velocidade da parede nesse ponto (rotação rígida com OMEGA)
        var vw = OMEGA * (-(py - CY));
        var vwy = OMEGA * (px - CX);

        var rvx = b.vx - vw, rvy = b.vy - vwy;       // velocidade relativa
        var vn = rvx * mx + rvy * my;                // componente na normal exterior
        if (vn > 0) {                                // em aproximação à parede
          var imp = (1 + REST) * vn;                 // reposicionar a componente normal
          b.vx -= imp * mx;
          b.vy -= imp * my;
        }
        // fricção de contacto (tangencial)
        var tx = my, ty = -mx;                        // tangente unitária
        var vt = rvx * tx + rvy * ty;
        b.vx -= WALL_FRIC * vt * tx;
        b.vy -= WALL_FRIC * vt * ty;
