        b.rot += (vt / BALL_R) * h;

        // separar: empurrar o centro de volta para dentro do polígono
        var push = BALL_R - g;
        b.x -= push * mx;
        b.y -= push * my;
      }
    }
  }

  function resolveBalls(h) {
    var MIN = 2 * BALL_R;
    for (var i = 0; i < balls.length; i++) {
      for (var j = i + 1; j < balls.length; j++) {
        var A = balls[i], B = balls[j];
        var dx = B.x - A.x, dy = B.y - A.y;
        var d2 = dx * dx + dy * dy;
        if (d2 >= MIN * MIN) continue;
        var d = Math.sqrt(d2);
        var nx, ny;
        if (d < 1e-9) { nx = 1; ny = 0; d = 0; }
        else { nx = dx / d; ny = dy / d; }

        // separação posicional (massas iguais)
        var push = (MIN - d) / 2;
        A.x -= push * nx; A.y -= push * ny;
        B.x += push * nx; B.y += push * ny;

        var rvx = A.vx - B.vx, rvy = A.vy - B.vy;
        var vn = rvx * nx + rvy * ny;
        if (vn > 0) {                                  // em aproximação
          var imp = (1 + REST) * vn / 2;
          A.vx -= imp * nx; A.vy -= imp * ny;
          B.vx += imp * nx; B.vy += imp * ny;
        }
        var tx = -ny, ty = nx;                         // tangente
        var vt = rvx * tx + rvy * ty;
        var fr = BALL_FRIC * vt / 2;                   // fricção de contacto
        A.vx -= fr * tx; A.vy -= fr * ty;
        B.vx += fr * tx; B.vy += fr * ty;
        var rs = (vt / (2 * BALL_R)) * h;              // spins contrapostos
        A.rot += rs;
        B.rot -= rs;
      }
    }
  }

  function clean() {
    var ang = polyAngle();
    var bi, i, a, mx, my, g;
    for (bi = 0; bi < balls.length; bi++) {
      var b = balls[bi];
      for (i = 0; i < N; i++) {
        a = ang + (i + 0.5) * (2 * Math.PI / N);
        mx = Math.cos(a); my = Math.sin(a);
        g = APO - ((b.x - CX) * mx + (b.y - CY) * my);
        if (g < BALL_R - 1e-9) return false;
      }
    }
    var lim = 2 * BALL_R - 1e-9;
    for (var i2 = 0; i2 < balls.length; i2++) {
      for (var j2 = i2 + 1; j2 < balls.length; j2++) {
        var dx = balls[j2].x - balls[i2].x;
        var dy = balls[j2].y - balls[i2].y;
        if (dx * dx + dy * dy < lim * lim) return false;
      }
    }
    return true;
  }

  // Garantia final, sem margens de tolerância: nenhuma bola fora do polígono
  // nem duas bolas sobrepostas no estado final de cada sub-passo.
  function hardSeparate() {
    for (var k = 0; k < 200; k++) {
      var changed = false;
      var ang = polyAngle();
      // paredes
      for (var bi = 0; bi < balls.length; bi++) {
        var b = balls[bi];
        for (var i = 0; i < N; i++) {
          var a = ang + (i + 0.5) * (2 * Math.PI / N);
          var mx = Math.cos(a), my = Math.sin(a);
          var g = APO - ((b.x - CX) * mx + (b.y - CY) * my);
          if (g < BALL_R) {
            var p1 = (BALL_R - g) + 0.01;
            b.x -= p1 * mx;
            b.y -= p1 * my;
            changed = true;
          }
        }
      }
      // pares
      var MIN = 2 * BALL_R;
      for (var i2 = 0; i2 < balls.length; i2++) {
        for (var j2 = i2 + 1; j2 < balls.length; j2++) {
          var A = balls[i2], B = balls[j2];
          var dx = B.x - A.x, dy = B.y - A.y;
          var d2 = dx * dx + dy * dy;
          if (d2 >= MIN * MIN) continue;
          var d = Math.sqrt(d2);
          var nx, ny;
          if (d < 1e-9) { nx = 1; ny = 0; d = 0; }
          else { nx = dx / d; ny = dy / d; }
          var p2 = (MIN - d) / 2 + 0.005;
          A.x -= p2 * nx; A.y -= p2 * ny;
          B.x += p2 * nx; B.y += p2 * ny;
          changed = true;
        }
      }
      if (!changed) break;
    }
  }

  function physicsStep(h) {
    var mul = Math.exp(-AIR_K * h);   // fricção do ar
    for (var i = 0; i < balls.length; i++) {
      var b = balls[i];
      b.vy += GRAV * h;               // gravidade
      b.vx *= mul; b.vy *= mul;
      b.x += b.vx * h;
      b.y += b.vy * h;
    }
    for (var it = 0; it < 8; it++) {
      resolveWalls(h);
      resolveBalls(h);
      if (clean()) break;
    }
    hardSeparate();
  }

  function advance(dt) {
    if (!(dt > 0)) return;
    var n = Math.max(1, Math.ceil(dt / MAX_H));
    var h = dt / n;
    for (var k = 0; k < n; k++) {
      physicsStep(h);
      t += h;
    }
