  function getState() {
    return {
      t: t,
      poly: {
        n: N,
        radius: POLY_R,
        cx: CX,
        cy: CY,
        angle: polyAngle(),
        periodSec: PERIOD
      },
      balls: balls.map(function (b) {
        return { id: b.id, x: b.x, y: b.y, r: BALL_R, vx: b.vx, vy: b.vy };
      })
    };
  }

  function step(dtSeconds) {
    manual = true;
    var dt = Number(dtSeconds);
    if (!isFinite(dt) || dt < 0) dt = 0;
    advance(dt);
    draw();
  }

  var globalObj = (typeof window !== 'undefined') ? window : globalThis;
  globalObj.__bench = { getState: getState, step: step };

  /* -------------------------- desenho --------------------------- */
  function draw() {
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);

    var bg = ctx.createRadialGradient(W / 2, H * 0.42, 40, W / 2, H / 2, 360);
    bg.addColorStop(0, '#1b2334');
    bg.addColorStop(1, '#0b0e14');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    // nonágono
    var ang = polyAngle();
    ctx.beginPath();
    for (var i = 0; i < N; i++) {
      var a = ang + i * (2 * Math.PI / N);
      var x = CX + POLY_R * Math.cos(a);
      var y = CY + POLY_R * Math.sin(a);
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fillStyle = 'rgba(52, 74, 118, 0.25)';
    ctx.fill();
    ctx.strokeStyle = '#6ea8ff';
    ctx.lineWidth = 4;
    ctx.lineJoin = 'round';
    ctx.shadowColor = 'rgba(110, 168, 255, 0.55)';
    ctx.shadowBlur = 14;
    ctx.stroke();
    ctx.shadowBlur = 0;

    // bolas (o número é desenhado por cima e gira com a bola)
    for (var bi = 0; bi < balls.length; bi++) {
      var b = balls[bi];
      ctx.save();
      ctx.translate(b.x, b.y);
      ctx.rotate(b.rot);
      var hue = (b.id * (360 / NUM) + 200) % 360;
      var grad = ctx.createRadialGradient(-5, -6, 2, 0, 0, BALL_R);
      grad.addColorStop(0, 'hsl(' + hue + ', 80%, 74%)');
      grad.addColorStop(1, 'hsl(' + hue + ', 72%, 44%)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(0, 0, BALL_R, 0, 2 * Math.PI);
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.35)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 13px "Segoe UI", system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(String(b.id), 0, 0.5);
      ctx.restore();
    }

    // HUD discreto
    ctx.fillStyle = 'rgba(226, 235, 250, 0.72)';
    ctx.font = '12px "Segoe UI", system-ui, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    ctx.fillText('t = ' + t.toFixed(2) + ' s    \u00b7    non\u00e1gono \u00b7 360\u00b0 em 7 s \u00b7 e = 0.82', 16, 24);
  }

  draw();

  /* ------------------- animação (rAF) --------------------------- */
  if (typeof requestAnimationFrame === 'function') {
    var last = null;
    requestAnimationFrame(function frame(now) {
      if (last === null) last = now;
      var dt = (now - last) / 1000;
      last = now;
      dt = Math.max(0, Math.min(dt, 0.05));
      if (!manual && dt > 0) advance(dt); // pára de avançar quando __bench.step toma a condução
      draw();
      requestAnimationFrame(frame);
    });
  }
})();
</script>
</body>
</html>
'''

