console.log('inv after total 5.5s =', invariants(s2));
console.log('t =', s2.t);

// velocity bounded (no blowup)?
const vmax = Math.max(...s2.balls.map(b => Math.hypot(b.vx, b.vy)));
console.log('max|v| after 5.5s =', vmax.toFixed(1));

// --- instance B: determinism of identical sequence ---
