console.log('fresh determinism:', JSON.stringify(C.getState()) === JSON.stringify(D.getState()));

// --- zero step / negative step ---
D.step(0); D.step(-3);
console.log('after 0/-3 steps, t =', D.getState().t, 'invariant =', invariants(D.getState()));
